insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('esp', 'intermediate', 'module', 'm01-the-fluid-at-the-intake', 1, 'In what order does the intake calculation walk from the reservoir to the rate the stage curve is read at?', '["The tank rates are converted first, and the intake pressure follows from the stream that results.", "The separator is applied to the producing gas oil ratio, and the black oil properties are then evaluated on what remains.", "Flowing bottomhole pressure less the annulus column gives the intake pressure, black oil properties at that pressure give the in situ rates and the free gas, and a separator then removes part of that gas before the stream reaches the impellers.", "The duty is set from the stage curve and the intake pressure is back calculated to match it."]'::jsonb, 2, 'Only the rate and the density of what is left are used by the rest of the design.'),
  ('esp', 'intermediate', 'module', 'm01-the-fluid-at-the-intake', 2, 'The published golden design gassyOffshore reports 2664.000000 bbl/d of liquid at depth, 2952.000000 bbl/d of total stream and 2750.400000 bbl/d through the pump. Which is the duty?', '["2750.400000 bbl/d, the liquid at depth plus only the free gas that survived the separator.", "2952.000000 bbl/d, since the whole stream arrives at the pump setting depth and a separator only changes where the gas goes after the impellers have passed it.", "2664.000000 bbl/d, because only liquid is pumped.", "The sum of the two tank rates in stb/d."]'::jsonb, 0, 'The other 201.600000 bbl/d of gas went up the annulus and never reaches the impellers.'),
  ('esp', 'intermediate', 'module', 'm01-the-fluid-at-the-intake', 3, 'A 400 ft annulus column on the published golden design highWaterCut costs 168.0000 psi, and a 600 ft column on the teaching well QUA-IBOE-4 costs the same 168.0000 psi. What accounts for that?', '["The annulus gradient is taken from the produced liquid gradient in both cases, so the two columns weigh the same per foot and the depths cancel by coincidence.", "The module floors the annulus column at 168.0000 psi, which is the largest credit it will give for fluid standing above the pump setting depth.", "Both wells were set 500 ft above their perforations.", "The longer column is the lighter one, at 0.2800 psi/ft against 0.4200 psi/ft."]'::jsonb, 3, 'Above the pump the annulus carries whatever gas has separated out, so the gassier well carries the lighter column, and how much lighter is a caller input.'),
  ('esp', 'intermediate', 'module', 'm01-the-fluid-at-the-intake', 4, 'Which single input error is the easiest way to overstate the pump intake pressure?', '["Setting the pump below the perforations, which the module rewards with a negative lift and a pressure credit added to rather than taken off the flowing bottomhole pressure.", "Using the produced liquid gradient in the annulus, which makes every consequence optimistic.", "Quoting the flowing bottomhole pressure in the wrong pressure base, which the module silently converts and so shifts the whole intake calculation by one atmosphere.", "Evaluating the solution gas at reservoir conditions, which raises the intake pressure directly and leaves the annulus column untouched by the error."]'::jsonb, 1, 'Nothing in the module objects, because the gradient it was handed is exactly the gradient it used.'),
  ('esp', 'intermediate', 'module', 'm01-the-fluid-at-the-intake', 5, 'How does the module compute the free gas that arrives at the intake?', '["The oil rate at the tank multiplied by the difference between the producing gas oil ratio and the solution gas at intake conditions, floored at zero, and then multiplied by the gas formation volume factor.", "The oil rate at the tank multiplied by the producing gas oil ratio, converted at the gas formation volume factor.", "A flash calculation at the intake pressure against a bubble point found by search.", "The solution gas at intake conditions multiplied by the oil rate at depth rather than at the tank."]'::jsonb, 0, 'On the published golden design gassyOffshore that is 240000.00 scf/d, which 0.001200 rb/scf turns into 288.000000 bbl/d.'),
  ('esp', 'intermediate', 'module', 'm01-the-fluid-at-the-intake', 6, 'On the published golden design highWaterCut the producing gas oil ratio is 200.0 scf/stb against 180.0 scf/stb in solution. Why is the resulting 8000.00 scf/d called fragile?', '["The gas formation volume factor of 0.001800 rb/scf carries more significant figures than either gas oil ratio does, so the product inherits a precision it was never entitled to and the barrels at depth cannot be trusted.", "The module floors free gas at zero, so any value this small is reported as zero anyway.", "It is what survives a cancellation of two close numbers, so a revision to either input that nobody would argue about moves it by a large fraction of itself.", "Free gas is estimated by correlation on wet wells rather than computed."]'::jsonb, 2, 'At 0.001800 rb/scf it becomes 14.400000 bbl/d at depth, next to 4084.000000 bbl/d of liquid.'),
  ('esp', 'intermediate', 'module', 'm01-the-fluid-at-the-intake', 7, 'Why does gas still in solution at the intake need no handling as far as the pump is concerned?', '["It is taken out by the separator before the impellers see it, so the annulus carries it away and the gas volume fraction through the pump falls to match.", "It is already inside the oil volume, counted by the oil formation volume factor, so it takes up no separate space in an impeller.", "It is compressed back into the oil by the first few stages, which raises the pressure fast enough that nothing breaks out before the discharge is reached.", "It weighs nothing, so it changes neither the density nor the gradient."]'::jsonb, 1, 'Only gas that has broken out is gas as far as an impeller is concerned.'),
  ('esp', 'intermediate', 'module', 'm01-the-fluid-at-the-intake', 8, 'The module carries a gas volume fraction of the whole stream and a gas volume fraction through the pump. Which of the two is compared against the published limits?', '["The fraction of the whole stream, since the limits are written on the gas the well makes rather than on what a separator leaves behind.", "Whichever of the two is larger, so that the verdict is conservative and the equipment is never specified light.", "Both, with the stream fraction taken against the handler maximum and the pumped fraction against the standard maximum.", "The fraction through the pump, always."]'::jsonb, 3, 'The stream fraction has no consumer at all past the point the separator is applied.'),
  ('esp', 'intermediate', 'module', 'm01-the-fluid-at-the-intake', 9, 'The teaching well QUA-IBOE-4 carries a stream fraction of 0.2587677725 and a pumped fraction of 0.1610792254. What does reading the wrong one cost?', '["A different class of equipment, since the stream figure reads as separatorRequired while the value the module actually returns is gasHandler.", "Nothing, because both figures fall between the same pair of published limits.", "A shift along the stage curve, which moves head per stage and efficiency together.", "A slightly heavier design gradient and nothing else."]'::jsonb, 0, 'Neither published design reaches the middle verdict, which is why this teaching well exists.'),
  ('esp', 'intermediate', 'module', 'm01-the-fluid-at-the-intake', 10, 'What do the two default gas limits of 0.10 and 0.25 each mark?', '["Below 0.10 the free gas is treated as dissolved and ignored, between the two the head per stage is degraded by a correction factor, and above 0.25 the module returns no design at all.", "The band of gas volume fraction inside which the stage curve stays valid.", "Below 0.10 a standard pump copes alone, between the two a gas handler goes in front of it, and above 0.25 the answer is a separator or another lift method.", "The lower and upper bounds on separator efficiency the module will accept."]'::jsonb, 2, 'Both are configurable inputs, so an operator with vendor limits sets their own.'),
  ('esp', 'intermediate', 'module', 'm01-the-fluid-at-the-intake', 11, 'Sweeping the separator efficiency on the teaching well QUA-IBOE-4 takes the rate through the pump from 3408.461538 down to 2526.461538 bbl/d. What happens to the density?', '["It falls from 52.070972 to 40.019905 lbm/ft3, because removing the heaviest phase from the stream leaves the impellers a lighter fluid to lift.", "It rises from 40.019905 to 52.070972 lbm/ft3, so the same feet of head now need more pressure.", "It holds at 40.019905 lbm/ft3 throughout, since the mixture density is computed on the whole stream before any venting is applied to it.", "It rises, but only above an efficiency of 0.70."]'::jsonb, 1, 'Sizing on the lighter stream density together with the vented rate takes the friendly half of each.'),
  ('esp', 'intermediate', 'module', 'm01-the-fluid-at-the-intake', 12, 'What does the gas verdict model about a pump running on a gassy stream?', '["Nothing, since it names a class of equipment and stops.", "A head degradation that grows with the gas volume fraction, applied to the reading taken off the stage curve at the duty.", "The performance of the gas handler it selects, so that the stages behind that handler can be read on a corrected curve.", "A surging threshold above which the stack is predicted to gas lock and the stage count is withheld."]'::jsonb, 0, 'A duty at 0.25876777 gas is read off the curve exactly as one at 0.00000000 would be.'),
  ('esp', 'intermediate', 'module', 'm01-the-fluid-at-the-intake', 13, 'Which quantities does the intake module decline to compute for itself?', '["The intake pressure, which the user supplies directly.", "The gas volume fraction through the pump and the verdict that follows from it.", "The free gas at standard conditions and its conversion to barrels at depth.", "The solution gas, the volume factors and the three densities, which all arrive as caller inputs at intake conditions, and the discharge pressure, which is a flowing traverse result."]'::jsonb, 3, 'It does report in situ viscosity and flags viscous service above 10 cSt without correcting for it.'),
  ('esp', 'intermediate', 'module', 'm01-the-fluid-at-the-intake', 14, 'On the published golden design gassyOffshore the separator vents 201.600000 bbl/d. What does that do to the fluid the impellers swallow?', '["It leaves the density unchanged at 50.53658537 lbm/ft3, because the vented gas comes out of the numerator and the denominator of the mixture in the same proportion.", "It lightens the pumped fluid by 3.26446175 lbm/ft3.", "It leaves them fluid 3.26446175 lbm/ft3 heavier, at 53.80104712 rather than 50.53658537 lbm/ft3.", "It changes the rate only, since density is a property of the phases."]'::jsonb, 2, 'The gradient moves with it, by 0.0226698733 psi/ft.'),
  ('esp', 'intermediate', 'module', 'm01-the-fluid-at-the-intake', 15, 'A designer sizes on the total stream at depth and then also specifies a gas handler. What has gone wrong?', '["Nothing, since sizing on the larger of the two rates and then specifying a handler for the gas that remains is the conservative reading of both published limits.", "The vented gas has been taken out once and left in once, because the venting is already inside the pumped fraction.", "The stage curve has been read outside its published rate range, which is what raised the handler recommendation in the first place and is not a gas question at all.", "The handler should have been chosen on the stream fraction instead."]'::jsonb, 1, 'The rate through the pump is the complete statement of what the impellers see.'),
  ('esp', 'intermediate', 'module', 'm02-density-and-gradient', 1, 'How is the mixture density of a three phase stream at the intake formed?', '["As the water cut weighting of the oil and water densities, with the gas ignored.", "As the sum of the three mass rates over the sum of the three volume rates at depth, which is not an average of the three densities and on a real well is not close to one.", "As the arithmetic mean of the oil, water and gas densities at intake conditions.", "As the tank rate weighting of the two liquid densities, corrected afterwards for gas."]'::jsonb, 1, 'On the published golden design gassyOffshore the two tank rates are equal while the in situ rates are 1440.000000 and 1224.000000 bbl/d.'),
  ('esp', 'intermediate', 'module', 'm02-density-and-gradient', 2, 'Equal tank rates of oil and water on gassyOffshore, at 48.00 and 64.00 lbm/ft3, give a liquid density at depth of 55.35135135 lbm/ft3 rather than the midpoint. Why?', '["The gas density of 6.00 lbm/ft3 is folded into the liquid figure first, which pulls it below the midpoint of the two phases it was built from.", "The water cut of 0.5000 is clamped before use.", "The two densities are quoted at the tank, not at depth.", "The volume factors moved the weighting before the density was computed, so the oil takes up more of the volume at depth."]'::jsonb, 3, 'The published golden design highWaterCut runs the other way, landing at 63.46425073 lbm/ft3 close to its water.'),
  ('esp', 'intermediate', 'module', 'm02-density-and-gradient', 3, 'Which density becomes the design gradient?', '["The density of the fluid the pump swallows, which is the liquid plus only the gas the separator left in.", "The density of the whole stream at depth, since that is the mixture the intake calculation reports and venting happens downstream of the impellers.", "The liquid density at depth, because a gradient is a liquid property and free gas is accounted for separately through its own fraction and verdict.", "The oil density at intake conditions."]'::jsonb, 0, 'On highWaterCut, with no separator, the two mixture densities agree at 63.25602186 lbm/ft3 and the choice cannot be made wrongly.'),
  ('esp', 'intermediate', 'module', 'm02-density-and-gradient', 4, 'What exactly does gradientFromDensity do to a density in lbm/ft3?', '["It multiplies by 0.433000, the rounded field constant the module also exports for the same conversion.", "It divides by 62.4 to reach a specific gravity and then multiplies by 0.433000 to reach the gradient.", "It divides by 144, which is exact arithmetic.", "It divides by 144 after checking that the density was evaluated at the intake pressure just computed."]'::jsonb, 2, 'There is no fitted constant in it and no fluid assumption at all.'),
  ('esp', 'intermediate', 'module', 'm02-density-and-gradient', 5, 'What is the consequence of carrying the whole stream gradient forward on a well that has a separator?', '["The head requirement is understated, which shortens the stack.", "The same pressure rise reads as more feet of head while the vented gas is also missing from the rate, so the design is built for a stream that exists nowhere in the well.", "Nothing, because the two gradients agree once the venting is accounted for.", "The gas volume fraction is compared against the wrong published limit."]'::jsonb, 1, 'On gassyOffshore the stream gradient is 0.0226698733 psi/ft light.'),
  ('esp', 'intermediate', 'module', 'm02-density-and-gradient', 6, 'A gradient of zero reaches the head calculation. What does the module do?', '["Total dynamic head returns NaN while the pressure difference is still reported, and the NaN then propagates into the stage count.", "A warning is raised at the point the gradient went bad, the pressure difference of 2000.0 psi is returned, and both the head and the stage count are withheld until a valid gradient arrives.", "It substitutes the rounded field constant 0.433000 and continues.", "It throws, because a zero gradient is not a physical fluid."]'::jsonb, 0, 'On the module''s own fixture the pressure difference reported alongside the NaN is 2000.0 psi.'),
  ('esp', 'intermediate', 'module', 'm02-density-and-gradient', 7, 'By how much do the module''s two forms of the same gradient conversion disagree?', '["By 0.0008242606 in relative terms, which is the deviation between HP_HEAD_DIVISOR in its pressure form and the familiar rounded 58824.", "By an amount that depends on the fluid, since the exact form carries a density while the rounded form carries a specific gravity and the two scale differently.", "By 0.433333333333 psi/ft per unit specific gravity.", "By 0.000333333333 psi/ft per unit specific gravity, which is 0.076982 percent."]'::jsonb, 3, 'The exact form is 62.4 divided by 144 and the rounded field constant PSI_PER_FT_SG is 0.433000.'),
  ('esp', 'intermediate', 'module', 'm02-density-and-gradient', 8, 'Where in the package do the two gradient forms actually meet on one well?', '["Inside the stage curve fit, where the head coefficients are converted from feet to psi and back at every reading.", "Inside sizePump, which computes the stage count on one form and the brake power on the other before returning both.", "Where the design chain divides a density while the diagnostics multiply a specific gravity.", "Inside the motor sizing, where the derated rating is turned into a gradient to check the fluid against the thrust bearing."]'::jsonb, 2, 'Hand one well a specific gravity computed as density divided by 62.4 and the two routes read different heads from the same pressures.'),
  ('esp', 'intermediate', 'module', 'm02-density-and-gradient', 9, 'The gap between the two routes is 3.832442 ft on gassyOffshore, 2.923126 ft on highWaterCut, 3.104070 ft on QUA-IBOE-4 and 0.558191 ft on IBENO-2. What is constant across the four?', '["The gap in feet, which is fixed by the two constants.", "The percentage, since every one of those gaps is 0.076982 percent of the head it sits on, so what it is worth in feet scales with the head.", "The specific gravity the diagnostics chain uses.", "The design gradient, which is the same on all four wells."]'::jsonb, 1, 'IBENO-2 is a short shallow stack, which is why its gap is the smallest of the four.'),
  ('esp', 'intermediate', 'module', 'm02-density-and-gradient', 10, 'Engines PR #109 examined five findings and changed exactly one. Why was the gradient disagreement not the one changed?', '["Both the goldens and the live application derive the specific gravity from the design gradient, so on every case that ships the two routes never meet.", "The disagreement is smaller than the acceptance band the goldens are compared at, so no test could have detected the edit either before or after it was made, which left nothing to prove.", "The exact form is wrong and the rounded form is right, so no edit was available.", "It was already covered by the fix made to the three diagnostic messages."]'::jsonb, 0, 'Editing either constant would move a number somebody is looking at today, to repair a case no shipped consumer produces.'),
  ('esp', 'intermediate', 'module', 'm02-density-and-gradient', 11, 'What is the convention that holds both conversions at once and loses nothing?', '["Compute the design gradient from the density and then round it to the same number of figures the field constant carries, which brings the two routes inside a tolerance nobody can measure.", "Take the specific gravity as the density divided by 62.4 and pass it to both chains, so one physically true value is used everywhere and neither chain carries a rounded constant.", "Define the specific gravity as the design gradient divided by 0.433000, so multiplying back returns that gradient identically.", "Use the exact form in the design chain and the rounded form nowhere."]'::jsonb, 2, 'The zeros in the disagreement column are exact rather than small, because the gap has been kept out of the one place it could show up.'),
  ('esp', 'intermediate', 'module', 'm02-density-and-gradient', 12, 'Which specific gravity is the published golden design gassyOffshore actually sized on?', '["0.8621962680, the physically true value formed as the pumped density divided by 62.4.", "0.8621962680, since the goldens were cut before the convention was written down and adopted.", "1.0144986827, which is the laundered figure the published golden design highWaterCut carries.", "0.8628600064, the value derived from the design gradient."]'::jsonb, 3, 'A designer who recomputes the value to be more careful is the one who breaks the agreement.'),
  ('esp', 'intermediate', 'module', 'm02-density-and-gradient', 13, 'What does the convention cost, honestly stated?', '["The number carried through the design sits 0.076982 percent off the fluid, a uniform residual bias that everything built on it shares.", "Nothing, since the disagreement has been removed entirely.", "A gap of 3.832442 ft on every well it is applied to.", "The loss of the exact division by 144 from the design chain."]'::jsonb, 0, 'Consistency between all the numbers built on it is what a convention buys.'),
  ('esp', 'intermediate', 'module', 'm02-density-and-gradient', 14, 'What check runs between the gradient the module is handed and the specific gravity it is handed?', '["The gradient is divided by the specific gravity and a warning fires when the quotient sits outside a narrow band around 0.433000, which catches an inconsistent pair before either chain runs.", "None, so the convention is enforced by the caller and by the gates and never by the arithmetic.", "The specific gravity is recomputed and the value given is overridden.", "Both are compared against the intake pressure just computed."]'::jsonb, 1, 'No warning exists for a well carrying two heads, and the difference arrives small enough to read as rounding.'),
  ('esp', 'intermediate', 'module', 'm02-density-and-gradient', 15, 'The espDesign.js docstring says the disagreement on a 3700 ft total dynamic head is about 2.8 ft. What is the standing of that sentence?', '["It is the published figure the convention was written against, so it is the number to quote whenever the cost of mixing the two routes has to be priced.", "It is a rounding of the gap on the published golden design gassyOffshore, whose head of 4978.341767 ft is the nearest real case the docstring could have meant.", "It is stale documentation worth correcting when the file is next opened, since no case in the package produces it.", "It is correct and nothing in the package depends on it."]'::jsonb, 2, 'The nearest real case is highWaterCut at 3797.140461 ft of head, whose gap is 2.923126 ft.'),
  ('esp', 'intermediate', 'module', 'm03-rate-at-depth', 1, 'Why is the water rate never an input on any of the three cases in this module?', '["It is derived from the water formation volume factor alone.", "It is read back from the liquid rate at depth once the volume factors are applied.", "It is set by the separator efficiency, which decides how much water is vented.", "It follows from the oil rate at the tank and the water cut, which is how 400.0 stb/d of oil at a cut of 0.9000 carries 3600.000000 stb/d of water on the published golden design highWaterCut."]'::jsonb, 3, 'A water cut given as a percentage rather than a fraction is clamped into a valid fraction rather than rejected.'),
  ('esp', 'intermediate', 'module', 'm03-rate-at-depth', 2, 'The liquid at depth is 1.11000000 times the tank liquid rate on gassyOffshore, 1.02100000 on highWaterCut and 1.17300000 on the teaching well QUA-IBOE-4. What does that spread say?', '["The multiple rises with the intake pressure, so a deeper well with a higher flowing bottomhole pressure swells further, and the three cases can be ordered on that basis alone.", "The multiple is a property of the fluid and has to be computed for the well in hand rather than carried as a rule of thumb.", "The multiple is bounded near 1.1 and a margin of that size covers it.", "The spread reflects the three separator efficiencies."]'::jsonb, 1, 'A wet well barely swells because water hardly expands, while an oily well with gas coming out of it swells hard.'),
  ('esp', 'intermediate', 'module', 'm03-rate-at-depth', 3, 'What makes the gas formation volume factor a different animal from the two liquid factors?', '["It is a unit change with a very large ratio inside it rather than a swelling factor near one.", "It is fitted by correlation inside the module while the liquid factors are caller inputs, which is why it varies so widely between the three cases.", "It is evaluated at standard conditions while the two liquid factors are evaluated at the intake, so it alone needs no pressure quoted with it.", "It is applied to the gas already in solution as well as to the free gas."]'::jsonb, 0, 'On QUA-IBOE-4, 630000.00 scf/d at 0.001400 rb/scf becomes 882.000000 bbl/d, more volume than the 776.461538 bbl/d of water on the same well.'),
  ('esp', 'intermediate', 'module', 'm03-rate-at-depth', 4, 'Bg is 0.001200, 0.001400 and 0.001800 rb/scf across the three cases in the reading. How should that spread be read?', '["As a monotone fall with intake pressure, which is why the lowest figure belongs to the case with the highest intake pressure of the three.", "As the spread the module smooths over when it interpolates a gas factor between cases it has already seen.", "As three separate reservoirs with three fluids, so no trend can be read off it.", "As evidence that one of the three values was lifted from a reservoir condition table and needs correcting downward."]'::jsonb, 2, 'It is exactly why the module will not guess the factor and insists on taking it as an input.'),
  ('esp', 'intermediate', 'module', 'm03-rate-at-depth', 5, 'A volume factor set is brought down from reservoir conditions. Which of the three errors is the loud one?', '["The water factor, because water is the largest phase on a wet well.", "The oil factor, because it is the lever on an oil well and sets the largest liquid rate.", "None of the three, since each is checked against the intake pressure just computed.", "The gas factor, because it multiplies a quantity thousands of times larger than everything around it, so the free gas at depth, the gas volume fraction, the mixture density, the gradient, the head and the verdict all move at once."]'::jsonb, 3, 'On an oil well the oil factor error is quiet and the design comes out only a little wrong.'),
  ('esp', 'intermediate', 'module', 'm03-rate-at-depth', 6, 'How is the rate through the pump defined?', '["The total stream at depth less the liquid the separator returns to the annulus, taken at the intake pressure rather than at the tank.", "The liquid rate at depth plus whatever free gas survived the separator.", "The total stream at depth.", "The tank liquid rate multiplied by the volume factors."]'::jsonb, 1, 'On the published golden design highWaterCut the separator efficiency is 0.0000, so the stream and the duty are the same 4098.400000 bbl/d.'),
  ('esp', 'intermediate', 'module', 'm03-rate-at-depth', 7, 'At its duty of 2750.400000 bbl/d and 60 Hz, what does gassyOffshore read off the stage?', '["A head of 25.93855015 ft, an efficiency of 0.6929775821 and a brake power of 0.6549201841 hp, all per stage.", "A head of 23.57901945 ft, an efficiency of 0.6706901367 and a brake power of 0.5579653060 hp per stage, which is what the teaching well QUA-IBOE-4 reads at its own duty.", "A head of 14.39891498 ft per stage, the figure the published golden design highWaterCut returns once its 50 Hz duty has been mapped onto the 60 Hz curve.", "A head of 28 ft, the catalogue value at best efficiency."]'::jsonb, 0, 'The reading sits inside the published range and in the recommended region.'),
  ('esp', 'intermediate', 'module', 'm03-rate-at-depth', 8, 'The published golden design highWaterCut runs at 50 Hz with a duty of 4098.400000 bbl/d. What does the engine do with that rate?', '["It reads the 60 Hz curve at 4098.400000 bbl/d directly and then scales the head that comes back by the frequency ratio cubed.", "It selects the catalogue curve nearest 50 Hz and interpolates between that curve and the 60 Hz curve at the duty.", "It maps it to 4918.080000 bbl/d on the 60 Hz curve, reads there and maps forward.", "It lowers the duty in proportion to the frequency before reading, since a slower pump passes less fluid at the same point on the curve."]'::jsonb, 2, 'The duty is a property of the well and the reference rate is a property of the reading, and the head per stage that comes back is 14.39891498 ft.'),
  ('esp', 'intermediate', 'module', 'm03-rate-at-depth', 9, 'What is the cost of reading the stage curve at 2952.000000 bbl/d rather than 2750.400000 bbl/d on gassyOffshore?', '["Only the stage count changes, since head per stage is flat across that interval.", "Nothing, because the two rates fall inside the same published range.", "The mixture density moves, which changes the gradient rather than the reading.", "The separator is silently uninstalled, since the gas is out of the impellers in the rate that should have been used and back in the rate that was, and the shift along the curve moves head, efficiency and region together."]'::jsonb, 3, 'It is the one place in the chain where a separator can be undone without a single warning.'),
  ('esp', 'intermediate', 'module', 'm03-rate-at-depth', 10, 'A duty of 3011.561538 bbl/d carries a gas volume fraction of 0.1610792254. How is the stage curve read at it?', '["With the head and the efficiency reduced by a gas correction derived from the fraction, which is the reason the module tracks that fraction through to the duty at all.", "Exactly as the same rate of pure liquid would be, with no head degradation, no efficiency penalty and no surging.", "With the gas volume taken out of the rate before the curve is read.", "With Hydraulic Institute factors applied automatically."]'::jsonb, 1, 'Gas is present in the rate and in the density, and nowhere else.'),
  ('esp', 'intermediate', 'module', 'm03-rate-at-depth', 11, 'What sets the region band a duty is reported in?', '["The reference rate against the best efficiency rate, downthrust below 0.75 of it and upthrust above 1.25.", "The gas volume fraction through the pump against the two published gas limits, which is why a gassy well is reported outside the recommended band more often than a wet one.", "The duty against the published rate range of the stage, so a duty inside that range is always reported as recommended whatever the best efficiency rate happens to be.", "The head per stage against the head at best efficiency."]'::jsonb, 0, 'The published golden design highWaterCut lands in downthrust and raises one warning about wear on the thrust washers.'),
  ('esp', 'intermediate', 'module', 'm03-rate-at-depth', 12, 'The downthrust warning fires on highWaterCut. What changes in its numbers because of it?', '["The head per stage is reduced, which is what lifts the stage count to 264 on that design.", "The efficiency at the duty is cut to 0.6745418519, which is the derated figure the warning refers to.", "Nothing, since the warning is mechanical rather than numeric.", "The shaft horsepower is raised to 172.55965200 hp to cover the extra thrust the washers carry."]'::jsonb, 2, 'Nothing in the head, the efficiency or the power moves when the region flag is raised.'),
  ('esp', 'intermediate', 'module', 'm03-rate-at-depth', 13, 'What conversions does this part of the module refuse to make?', '["It converts tank rates to in situ rates one way only, with no path back from an in situ rate, no surface facility model beyond the pump and no derivation of the volume factors themselves.", "It refuses to convert a water cut given as a percentage.", "It refuses any rate conversion once free gas is present in the stream.", "It refuses to convert a rate at a frequency other than 60 Hz."]'::jsonb, 0, 'The volume factors, the solution gas and the three densities arrive as inputs at intake conditions and are used exactly as given.'),
  ('esp', 'intermediate', 'module', 'm03-rate-at-depth', 14, 'Moving the duty moves two things about the stage at once. Which two, and what does each drive?', '["The head per stage and the efficiency, which together set the stage count and the region, while brake power comes from the motor nameplate rather than from the stage at all.", "The head per stage, which divides the requirement to give the stage count, and the brake power per stage, which multiplies it to give the shaft power.", "The efficiency and the region, which together set the warnings raised.", "The stage count and the shaft power, which are read straight off the curve."]'::jsonb, 1, 'gassyOffshore carries 192 stages at 125.69771587 hp and highWaterCut 264 stages at 172.55965200 hp.'),
  ('esp', 'intermediate', 'module', 'm03-rate-at-depth', 15, 'In situ viscosity above 10 cSt is reported. What does the module then do about it?', '["It applies Hydraulic Institute correction factors from its own table and reports the corrected head, efficiency and power alongside the uncorrected values for comparison.", "It withholds the reading at the duty until a viscosity correction has been supplied, since the fit behind the curve was built on a water test and cannot be stretched.", "It states that the water curve overstates head and efficiency, and waits for Hydraulic Institute factors from the user.", "It derates the efficiency by a fixed factor and carries on."]'::jsonb, 2, 'Correction factors are applied only when a user hands them over.'),
  ('esp', 'intermediate', 'module', 'm04-total-dynamic-head', 1, 'Total dynamic head on the published gassyOffshore design comes from a discharge of 3200.0 psia, an intake of 1340.0000 psia and a gradient of 0.3736183828 psi/ft. How is the 4978.341767 ft formed?', '["The pressure the pump must add, 1860.0000 psi, is divided by the gradient of the fluid inside the pump, so the head is one division and the gradient is half of it.", "The three named parts are computed first and then summed.", "The 1860.0000 psi is divided by the field constant 0.433000.", "The pump setting depth of 7000 ft TVD is added to a friction allowance."]'::jsonb, 0, 'The published highWaterCut design runs the same single division, 1668.0000 psi over 0.4392779296 psi/ft, and lands on 3797.140461 ft.'),
  ('esp', 'intermediate', 'module', 'm04-total-dynamic-head', 2, 'What does the breakdown function actually do with the net lift, the friction and the wellhead term it is handed?', '["It refuses any set of parts that fails to close.", "It recomputes the head from the two pressures and the gradient, then reports the residual between that head and the sum of the three parts as a check on the caller.", "It adds them and returns the sum, without ever going back to the two pressures.", "It solves for the friction as the residual needed to make the three parts close on the head the two pressures gave, which is why the closure always prints as zero."]'::jsonb, 2, 'Hand it three parts taken from three different wells and it returns their sum without comment, so the closure check is the reader''s work rather than the package''s.'),
  ('esp', 'intermediate', 'module', 'm04-total-dynamic-head', 3, 'The three parts summed against the head the two pressures gave leave 0.000000000000 ft on both published designs. What does that closure demonstrate?', '["That the friction term was fitted to make the total close.", "That the parts were derived from the same pressures and the same gradient, so the closure is a property of the derivation rather than a test the package performs.", "That the package validates the decomposition internally, rebuilding the head from the intake and discharge pressures and comparing it against the sum before it agrees to return anything to the caller.", "That the gradient behind the head is exact to twelve decimal places."]'::jsonb, 1, 'The teaching well QUA-IBOE-4 closes the same way at 4032.187516 ft, where the residual prints with a leading minus because the last bit of a double fell the other way.'),
  ('esp', 'intermediate', 'module', 'm04-total-dynamic-head', 4, 'On the published gassyOffshore design 1340.0000 psia over 0.3736183828 psi/ft is 3586.547295 ft, against a pump set at 7000 ft TVD. What is the net vertical lift?', '["7000 ft, because the pump has to lift from the depth at which it is set, that being the only depth the design was handed.", "3586.547295 ft, the height of fluid standing above the intake, which is the column the stages have to move to surface.", "7500 ft, the perforation depth, because the lift begins where the fluid enters the wellbore rather than where the pump happens to sit.", "3413.452705 ft, the part of the hole the fluid does not already fill."]'::jsonb, 3, 'The fluid level here is computed from an intake pressure and a gradient, so it inherits the error in both, and it is not a sonic shot.'),
  ('esp', 'intermediate', 'module', 'm04-total-dynamic-head', 5, 'gassyOffshore sits at 7000 ft TVD carrying 3413.452705 ft of net lift while highWaterCut sits at 5800 ft TVD carrying 3678.336385 ft. Why does the deeper pump have the smaller lift?', '["The deeper well runs the lighter fluid, so its feet come cheaper.", "The head requirement is smaller on the deeper case, so all three of its parts including the lift are scaled down in proportion to the total.", "Its intake pressure supports a taller column, 3586.547295 ft against 2121.663615 ft, and only the empty part of the hole is lift.", "Lift is measured from the perforations rather than from the pump."]'::jsonb, 2, 'The teaching well QUA-IBOE-4 makes the point again with the deepest pump of the three at 7600 ft TVD and a lift of only 2973.323299 ft.'),
  ('esp', 'intermediate', 'module', 'm04-total-dynamic-head', 6, 'Where does the friction term in this three part reading come from?', '["It is what remains once the tubing column and the wellhead pressure are taken out of the discharge pressure, so it is a residual rather than anything this module modelled.", "A pipe correlation run on tubing size, roughness and duty rate.", "A fixed share of the requirement, tuned case by case.", "The gap between the two published golden designs."]'::jsonb, 0, 'On gassyOffshore that residual is 184.6713 psi, and the friction the breakdown quotes as a pressure is the same 184.6713 psi because the two are one statement.'),
  ('esp', 'intermediate', 'module', 'm04-total-dynamic-head', 7, 'A discharge pressure supplied too high moves the head. Which single part of the split absorbs the whole of that error?', '["The net lift, because the fluid standing above the intake is computed from the pressure difference the discharge sets, so a taller column shortens the lift.", "The wellhead term, because the wellhead pressure is itself derived by subtracting the tubing column from whatever discharge pressure was supplied.", "All three move by the same proportion.", "The friction, since the lift is built from the intake pressure and the wellhead term from the wellhead pressure."]'::jsonb, 3, 'That is why the friction bucket is where every error in this reading lands, and why a friction share on its own says nothing about the string.'),
  ('esp', 'intermediate', 'module', 'm04-total-dynamic-head', 8, 'Friction is 12.0202 percent of the requirement on the teaching well IBENO-2 and 1.3302 percent on the published highWaterCut design. What follows about the two tubing strings?', '["highWaterCut must carry the rougher tubing, since it moves the larger rate.", "Nothing follows, because a share is set by the size of the whole requirement as much as by the friction itself, and IBENO-2''s 12.0202 percent is only 87.157303 ft.", "IBENO-2 runs the tighter string, since 12.0202 percent against a requirement of 725.090193 ft works out at roughly nine times the pressure loss per foot of tubing that highWaterCut sustains while passing 4098.400000 bbl/d.", "IBENO-2 must be flowing at the higher velocity of the two."]'::jsonb, 1, 'highWaterCut puts 4098.400000 bbl/d down its string for that 1.3302 percent, which is the largest rate of the four cases and the smallest friction share.'),
  ('esp', 'intermediate', 'module', 'm04-total-dynamic-head', 9, 'A designer computes a tubing friction from a pipe correlation and adds it to a head already built from the intake and discharge pressures. What has gone wrong?', '["The friction sits inside the difference between the two pressures already, so it is counted twice.", "Nothing, provided the correlation is evaluated at the duty rate through the pump rather than at the tank liquid rate.", "The correlation returns a pressure while the head is in feet, so the two cannot be added until the gradient of the pumped fluid has converted one of them.", "The head from the two pressures excludes friction by construction, so the addition is right and the only error is that the wellhead term then gets counted twice."]'::jsonb, 0, 'On gassyOffshore the term added a second time is worth 494.277929 ft, because the discharge pressure was marched at the design rate with the friction already in it.'),
  ('esp', 'intermediate', 'module', 'm04-total-dynamic-head', 10, 'The wellhead pressures used to split these four heads are 400.0, 30.0, 220.0 and 180.0 psia. What kind of numbers are they?', '["Published golden values cut alongside the two designs.", "Flowline pressures returned by the module''s own facility model.", "Teaching inputs supplied so that the three part split can be shown, rather than fields the golden cases carry, and the difference is worth keeping straight whenever the split is quoted.", "Measured wellhead readings taken from the four wells."]'::jsonb, 2, 'This module has no flowline, no choke and no separator pressure in it, so it cannot say whether any of the four is the right thing to design against.'),
  ('esp', 'intermediate', 'module', 'm04-total-dynamic-head', 11, 'QUA-IBOE-4 carries 220.0 psia at the wellhead and IBENO-2 carries 180.0 psia, yet IBENO-2 has the larger wellhead share of its head. Why?', '["IBENO-2 runs the lighter fluid of the two, so each psia at its wellhead buys more feet of head than the same pressure buys on QUA-IBOE-4.", "Share is measured against the whole requirement, and IBENO-2 needs only 725.090193 ft of it in total.", "The QUA-IBOE-4 term is converted at the gradient of the whole stream rather than at the gradient of the pumped fluid, and that is what suppresses its share of the requirement.", "IBENO-2 has the deeper pump of the two."]'::jsonb, 1, 'IBENO-2 is in fact the heavier fluid at 0.4206373262 psi/ft, so its 180.0 psia buys only 427.922081 ft, and that still comes to 59.0164 percent of a short requirement.'),
  ('esp', 'intermediate', 'module', 'm04-total-dynamic-head', 12, 'Why is a wellhead pressure quoted in gauge a problem in this chain?', '["Gauge pressures cannot be divided by a gradient at all.", "The gauge convention also changes the gradient the term is converted at, because the specific gravity standing behind that gradient is itself defined against an absolute reference pressure.", "It makes the head come back NaN.", "Every pressure here is absolute, so a gauge value shifts the wellhead term by an atmosphere nobody wrote down."]'::jsonb, 3, 'The companion mistake is converting the wellhead pressure at the whole stream gradient, which on gassyOffshore is lighter by 0.0226698733 psi/ft than the fluid actually inside the pump.'),
  ('esp', 'intermediate', 'module', 'm04-total-dynamic-head', 13, 'A designer trained on pipelines builds the requirement as friction plus wellhead pressure. What does leaving the net lift out do to the stack?', '["It leaves the count broadly right, since the net lift and the wellhead term overlap on any well whose fluid stands high above the intake.", "It overstates the count, because friction and wellhead pressure are then both paid for twice once the lift has been dropped from the sum.", "It understates the stage count by roughly an order of magnitude on these cases.", "It shifts the whole of the error into the friction term, which is where every other error in this reading lands as well."]'::jsonb, 2, 'The term dropped is the majority of the number on three of the four cases, and it reaches 96.8712 percent of the requirement on the published highWaterCut design.'),
  ('esp', 'intermediate', 'module', 'm04-total-dynamic-head', 14, 'The package carries the gradient conversion twice, as 62.4 divided by 144 and as the rounded 0.433000. What keeps the two routes from disagreeing on a shipped case?', '["The convention of deriving the specific gravity from the design gradient by dividing by 0.433000, which returns that gradient identically and leaves the two routes 0.000000000000 ft apart.", "A guard that rejects a specific gravity inconsistent with the gradient.", "The engines review replaced 0.433000 with the exact form.", "The 0.076982 percent gap falls below a reporting tolerance."]'::jsonb, 0, 'Mixing the two routes on one well is worth 3.832442 ft on gassyOffshore, 2.923126 ft on highWaterCut, 3.104070 ft on QUA-IBOE-4 and 0.558191 ft on IBENO-2.'),
  ('esp', 'intermediate', 'module', 'm04-total-dynamic-head', 15, 'What does a total dynamic head of 4978.341767 ft say about the stage that has to make it?', '["That the duty must sit inside the published rate range, because a head this large could not be assembled from a stage reading taken off the end of the fit.", "Nothing at all, since the head is a requirement and carries no verdict on any pump.", "That the stage runs in its recommended region, because the breakdown closes to 0.000000000000 ft only when every reading behind it is in range.", "That the stack will be a tall one."]'::jsonb, 1, 'The same head stands whether the stage making it runs in its recommended band or well off the end of its published data, which is why the region is read separately.'),
  ('esp', 'intermediate', 'module', 'm05-sizing-the-stack', 1, 'QUA-IBOE-4 divides out at 171.00742988 stages. Why is it given 172?', '["Because a spare stage is added as a design margin.", "A ceiling has no tolerance and no threshold, so a sliver of a stage past a whole number costs a whole stage.", "Because the count is rounded to the nearest whole stage, and 171.00742988 sits closer to 172 than to 171 once the head per stage has been read at the duty rate.", "Because the head per stage was read outside the published range."]'::jsonb, 1, 'Rounding that case to nearest would take the count below 172, and no warning in this package fires on a stack that is short of its requirement.'),
  ('esp', 'intermediate', 'module', 'm05-sizing-the-stack', 2, 'What does the stage count refuse to compute?', '["A head per stage read from outside the published rate range, which returns NaN until the caller hands over a reading from inside the data.", "A duty sitting in downthrust, refused because the stages would wear on their thrust washers long before the stack made its head.", "A requirement larger than the head an available stack could make, since no whole count would satisfy it.", "A head per stage of zero and a negative one, both returning NaN."]'::jsonb, 3, 'The published highWaterCut design is sized at 264 stages with its duty in downthrust and one warning raised, and the count comes back all the same.'),
  ('esp', 'intermediate', 'module', 'm05-sizing-the-stack', 3, 'The shaft horsepower and the stack brake power that come back from one sizing differ. By exactly what?', '["By the ratio of the head the stack makes to the head the duty requires, which is an identity holding to the last bit a double carries rather than an approximation.", "By the stage efficiency read at the duty rate.", "By a fixed allowance the package adds for shaft losses.", "By an amount that drifts with the case, as two models do."]'::jsonb, 0, 'The ratio can be formed before either power is computed: multiply the stage count by the head per stage and divide by the head required.'),
  ('esp', 'intermediate', 'module', 'm05-sizing-the-stack', 4, 'Why must the two brake powers stand in the ratio of the two heads?', '["Both powers are read from the same point on the published curve.", "Because the package rereads the stage efficiency at the head the stack makes, and the two efficiency readings then differ by exactly the same proportion as the two heads do.", "Hydraulic power is linear in head at a fixed rate and gravity, and rounding the count moves the head without moving the rate the efficiency is read at.", "Because the stage count is a whole number and both powers are formed by multiplying a per stage brake power by it, so any common factor between them cancels before either is reported."]'::jsonb, 2, 'An engine that did reread the efficiency at the head made would break the identity, which is why checking it on a report is worth the minute it takes.'),
  ('esp', 'intermediate', 'module', 'm05-sizing-the-stack', 5, 'Across four cases the power ratio and the head ratio differ by at most 0.0000000000000004, and a sweep from 550 ft to 900 ft never exceeds 0.0000000000000002. What does that establish?', '["That the two powers come from the same line of code.", "That the sweep was run too coarsely to separate them.", "That the head per stage was read to sixteen figures.", "That the relationship is an identity in this engine''s arithmetic, because an agreement between two separate models would drift with the case rather than sit at the last bit of a double."]'::jsonb, 3, 'The sweep runs fifteen head requirements on the short teaching stack, and on most of its steps the difference reads as a clean zero.'),
  ('esp', 'intermediate', 'module', 'm05-sizing-the-stack', 6, 'The rounding margin is 0.037359 percent of the head required on a 192 stage stack and 2.567658 percent of it on a 33 stage stack. What sets that spread?', '["The short stack simply carries the larger fraction of a stage rounded away.", "The margin is bounded by one stage rather than by a percentage, so the fewer stages share it, the larger a share of the requirement it becomes.", "The shorter stack is sized on a stage making less head, so the same fraction of a stage rounded away is worth proportionally more feet against the requirement the stack was cut to meet.", "Tall stacks are sized to a tighter tolerance."]'::jsonb, 1, 'The 33 stage case in fact rounds away 0.82611546 of a stage against 0.99257012 on a 172 stage case, so it carries less slack in stages and more than four times the percentage.'),
  ('esp', 'intermediate', 'module', 'm05-sizing-the-stack', 7, 'A reviewer reads the gap between the two powers as rounding noise. What has that reading cost them?', '["The gap is predictable before either power is computed, so its size on a report is a statement about how many stages the stack has.", "Nothing yet, since the gap is genuinely noise until a stack is short enough that cancellation between two nearly equal heads begins to dominate the difference.", "The gap is a safety allowance the sizing chose deliberately, so reading it as noise loses the record of a margin somebody signed off when the stack was cut.", "The gap moves with the drive frequency."]'::jsonb, 0, 'Noise has no size a reader expects, so someone holding that view will accept two powers sitting far apart instead of asking how short the stack is.'),
  ('esp', 'intermediate', 'module', 'm05-sizing-the-stack', 8, 'Moving the requirement on the short teaching stack from 700 ft to 720 ft takes the margin from 3.024489 percent to 0.162698 percent while the count stays at 32. What does that show?', '["The margin falls as the requirement rises, so a taller requirement always buys a tighter fit against the head the stack can make.", "The stage count carries the design intent and the margin only reports how much of the last stage the requirement has eaten since the count last stepped.", "The margin is a sawtooth, so no single reading of it characterises a design.", "The head per stage moved between the two requirements, and that is what took the margin down while leaving the count where it was."]'::jsonb, 2, 'The same stack goes the other way between 650 ft and 680 ft, where the margin climbs from 0.547939 percent to 2.740414 percent as the count steps from 29 to 31.'),
  ('esp', 'intermediate', 'module', 'm05-sizing-the-stack', 9, 'How is the head a stack makes formed, and why does it always meet the requirement?', '["It is the stage count times the head per stage, and the count was rounded up, so the product meets or exceeds what was asked for.", "It is the requirement plus the margin the sizing carries, which is why the two always agree to within the fraction of a stage the ceiling had to buy on the case in hand.", "It is the requirement read back, since the count was chosen to match it.", "It is the head per stage times the unrounded division."]'::jsonb, 0, 'That head is what the stack makes at the duty rate and at no other rate, so it is one point on a curve rather than a promise the well will take that rate.'),
  ('esp', 'intermediate', 'module', 'm05-sizing-the-stack', 10, 'Two powers come back from one sizing. Which one is the electrical chain in this package built on, and why does the choice matter?', '["The stack brake power, which is what the published sizing method takes.", "The hydraulic power, being the one free of stage efficiency.", "Whichever of the two is larger on the case in hand.", "The shaft horsepower at the head the duty requires, so a report that sizes a motor on the stack brake power and then draws its amps from the shaft power is inconsistent by exactly the rounding margin."]'::jsonb, 3, 'On the short teaching stack that inconsistency is 0.76450191 hp sitting on a 29.77428389 hp shaft, which is large enough to notice if you know what it is.'),
  ('esp', 'intermediate', 'module', 'm05-sizing-the-stack', 11, 'The published sizing method takes brake power at the head the stack makes, while this package builds its electrical chain on the power at the head required, understating by 0.04695948 hp on gassyOffshore and 0.76450191 hp on the short teaching stack. What was done about it?', '["It was fixed in the engines review by moving the electrical chain onto the stack brake power, which removed an understatement running in the non conservative direction on every case.", "It was recorded for a human decision and not fixed, because every number in this engine is consumed by a live application.", "It was adjudicated correct on the ground that the two powers are separated only by an integer rounding, so no consumer could ever observe a difference between them.", "It was dismissed as a documentation error."]'::jsonb, 1, 'Measured against the stack brake power, that same understatement is 0.037345 percent on gassyOffshore and 2.503380 percent on the short teaching stack.'),
  ('esp', 'intermediate', 'module', 'm05-sizing-the-stack', 12, 'gassyOffshore returns a hydraulic power of 87.10569922 hp beside a shaft horsepower of 125.69771587 hp. What separates the two?', '["The specific gravity of the pumped fluid, 0.8628600064.", "The rounding of the stage count, which lifts the head the stack makes above the head required and carries the brake power up with it by the ratio of the two heads.", "The stage efficiency at the duty, 0.6929775821, since brake power is hydraulic power over efficiency.", "The stage count of 192."]'::jsonb, 2, 'highWaterCut reads the same pair as 116.39870723 hp against 172.55965200 hp at an efficiency of 0.6745418519, so three powers come out of one sizing.'),
  ('esp', 'intermediate', 'module', 'm05-sizing-the-stack', 13, 'highWaterCut runs at 50 Hz with a duty of 4098.400000 bbl/d. Where is its head per stage of 14.39891498 ft read?', '["At an equivalent 4918.080000 bbl/d on the 60 Hz curve.", "At 4098.400000 bbl/d on a curve the package rebuilds for 50 Hz from the published catalogue points.", "At 4098.400000 bbl/d on the 60 Hz curve, with the affinity law applied to the head after the reading is taken.", "At the best efficiency rate of the stage, because a duty in downthrust is read at the nearest recommended point."]'::jsonb, 0, 'Slower drive means less head per stage, which is why that design needs 264 stages for a smaller requirement than the one 192 stages covers.'),
  ('esp', 'intermediate', 'module', 'm05-sizing-the-stack', 14, 'A fluid of 20 cp at 58 lbm/ft3 is 21.517241 cSt, past the 10 cSt flag, and no correction factors were supplied. What does adding stages do about that?', '["It restores the head the viscous fluid loses.", "Nothing, because the head per stage came back overstated and unchanged, and multiplying an overstated reading by a larger count only spreads the same error further.", "It moves the duty out of the viscous band.", "It forces the correction factors to be applied."]'::jsonb, 1, 'Published factors of 0.85 on head and 0.70 on efficiency take a 28.00000000 ft stage to 23.80000000 ft and a 0.7000000000 efficiency to 0.4900000000, which is a different pump rather than a longer one.'),
  ('esp', 'intermediate', 'module', 'm05-sizing-the-stack', 15, 'A report describes a stack as carrying 2.567658 percent of spare head. What is wrong with putting it that way?', '["It should be quoted in feet instead.", "The figure is right but incomplete, because the package compares it against a threshold of its own and raises a warning whenever the spare head falls under a single stage.", "Nobody chose it, since it is the remainder of an integer division rather than a design margin.", "The spare head is measured at the duty rate alone, so it ought to be quoted as a band across the rate range the well is expected to move through over its life."]'::jsonb, 2, 'The margin is not carried into the warnings, not compared against anything, and no threshold in the package fires on it.'),
  ('esp', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'Working a design in order, what has to be built before the black oil properties can be evaluated at all?', '["The stage count.", "The total dynamic head, because the pressure the pump must add fixes the range over which the volume factors and the solution gas have to stay valid.", "The pump intake pressure, since it sets the conditions those properties are read at.", "The rate through the pump, because the volume factors are evaluated at whatever rate the stage curve is going to be read at once the separator has vented."]'::jsonb, 2, 'Sorting the conditions into the chain before any arithmetic starts is also how you notice which of the rates you were handed are at the tank and which are at depth.'),
  ('esp', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'Why does an error made early in an ESP design survive all the way to the end of it?', '["Each step consumes the one before it and nothing later looks back, so a wrong intake pressure arrives at the stage count as an ordinary looking number.", "The warnings in the package fire only on the last step.", "The head requirement is rounded up, which hides it.", "Errors cancel between the gradient and the rate."]'::jsonb, 0, 'That is why the order of work matters more than any single formula in it, and why the checks are placed where an error would otherwise become invisible.'),
  ('esp', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'How is the friction identity checked on a finished reading?', '["Sum the three parts and subtract the head the two pressures gave.", "Divide the friction in feet by the head required.", "Run a pipe correlation at the duty rate through the pump on the tubing size and its roughness, then compare the pressure loss it returns against the friction term the breakdown quotes for the same case.", "Take the discharge pressure less the tubing column less the wellhead pressure and compare it against the friction the breakdown reports, which is 184.6713 psi both ways on gassyOffshore."]'::jsonb, 3, 'The same check on the published highWaterCut design reads 22.1880 psi from both directions, and the wellhead pressure it needs is a teaching input rather than a field the golden carries.'),
  ('esp', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'On gassyOffshore the two gradient routes agree to 0.000000000000 ft on one specific gravity and part by 3.832442 ft on another. Which route holds them together?', '["Deriving the specific gravity from the pumped mixture density by dividing by 62.4, that being the physically true value of the two.", "Deriving the specific gravity from the design gradient.", "Deriving the specific gravity from the whole stream density, since that is the fluid the published designs were originally cut on.", "Deriving the specific gravity from the head requirement, by dividing the pressure the pump adds by the head in feet and then by 0.433000."]'::jsonb, 1, 'The laundered value is already what the sizing is handed, 0.8628600064 on that design and 1.0144986827 on the published highWaterCut design.'),
  ('esp', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'What check does a rounding margin of 0.99257012 of a stage pass, and what would fail it?', '["It stays under a whole stage, which the margin always must, and anything reaching or exceeding one stage would mean the count had been rounded somewhere other than upward.", "It sits under the package''s own spare head threshold.", "It is under the standard gas limit of 0.10.", "It clears the 10 cSt viscous service flag."]'::jsonb, 0, 'The tallest of the four stacks rounds away only 0.07170260 of a stage, so the check is a bound rather than a typical value.'),
  ('esp', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'A design uses 50.53658537 lbm/ft3 where 53.80104712 lbm/ft3 belongs. Which failure is that?', '["Using a gas density where a liquid density belongs.", "Weighting oil and water by the water cut rather than by the two rates at depth, which on a well produced at equal tank rates lands near the midpoint of the two phase densities.", "Taking the whole stream density where the pumped mixture density is wanted, on a well whose separator has vented.", "Reading the liquid density at tank conditions rather than at the intake, so the volume factors never enter the weighting between the oil and the water at all."]'::jsonb, 2, 'It is the friendly error in both directions at once, because a lighter fluid gives more feet of head for the same pressure while the vented gas is also missing from the rate.'),
  ('esp', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'A graded design problem runs on conditions of its own. What actually carries across from a worked example?', '["The head requirement, which changes little between wells once the pump has been set at a comparable depth in a comparable fluid.", "The order of the work, and the checks that catch the usual mistakes.", "The stage count, since the same catalogue stage is used and the count follows the requirement closely across similar duties.", "The gradient, because the design gradient is a property of the catalogue stage rather than of the fluid the well happens to produce."]'::jsonb, 1, 'Sorting the conditions into the chain, building the intake pressure first and taking the fluid the pump swallows rather than the whole stream are the steps that transfer, while every number in them is refitted to the well in hand.'),
  ('esp', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'A duty of 4098.400000 bbl/d at 50 Hz becomes 4918.080000 bbl/d somewhere in the reading. What is that second number for?', '["It is the best efficiency rate of the stage.", "It is the duty corrected for the free gas present at depth.", "It is the rate the well would deliver if the drive were taken back to its reference frequency, so it is the number the head requirement ought to be built at instead of the duty.", "It is the equivalent rate on the 60 Hz curve, which is where the head per stage is actually read."]'::jsonb, 3, 'The duty rate is a property of the well while the reference rate is a property of the reading, and forgetting the drive frequency confuses the two.'),
  ('esp', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'This tier claims that a head, a gradient and a rate mean nothing until one thing has been said about them. What is it?', '["Which drive frequency they were read at.", "Whether they came from a published case.", "Which fluid they belong to, since the pump swallows something nobody measured directly and every number after the intake is that fluid carried forward.", "Which of the two gas limits they clear."]'::jsonb, 2, 'That claim is what ties the five modules together, from the separator that changes the density to the gradient that turns a pressure rise into feet.'),
  ('esp', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'This tier ends with a head requirement and a stage count. What is that still short of?', '["The machine that turns the stack, so a stage count with no shaft power behind it is a shopping list.", "The duty rate at depth.", "The head the stack actually makes, which cannot be formed until a motor has been chosen and its derated rating fixes how many stages may be turned at once.", "The gas volume fraction verdict, since the equipment class is settled only once the count is known and the stack length can be compared against the handler limit."]'::jsonb, 0, 'An ESP design is one number carried through four translations, and turning a well into a head requirement and a stack is the first two of them.'),
  ('esp', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'Two gradient conversions in this package disagree by 0.076982 percent, priced in feet on four separate cases, and the review left both alone. What was the professional output?', '["A warning raised whenever the two routes are mixed.", "A stated convention and a test that it holds, because no shipped consumer produces the case where the two routes actually meet.", "A patch replacing the rounded 0.433000 with the exact form, on the reasoning that a reproducible disagreement priced on four separate cases has to be removed before anything is built on it.", "A deprecation of the rounded field constant."]'::jsonb, 1, 'The disagreement is reachable only by computing a specific gravity some other way and handing it to the diagnostics, which nothing that ships does.'),
  ('esp', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'Of five findings examined in the engines review of this wave, how many were changed, and what governed that?', '["All five, once each had been priced on a published case.", "None, since the goldens would have had to be recut.", "Three, being the ones with a published rule behind them.", "One was changed, because every one of these engines feeds a live application and a numeric edit moves a number somebody is looking at today."]'::jsonb, 3, 'The one that changed added a decimal place to three diagnostic messages and altered no arithmetic at all, which is why it was safe to make.'),
  ('esp', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'Which density becomes the gradient that the head requirement is divided by?', '["The density of the fluid the pump swallows, once the separator has taken its share of the gas.", "The annulus density above the pump.", "The density of the whole stream at depth, since that is the mixture the free gas at intake conditions was added to in the first place.", "The density of the liquid at depth, because the gas is accounted for separately by the gas volume fraction and the verdict that follows from it."]'::jsonb, 0, 'On a design with no separator the two candidate densities are the same number, which is exactly why the choice cannot be practised on such a case.'),
  ('esp', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'The annulus column subtracted from the flowing bottomhole pressure is measured over which distance?', '["From the pump up to surface.", "From the perforations to surface, because the annulus stands open to the wellhead and the whole of that column presses down on the intake of the pump.", "From the perforations to the pump, floored at zero rather than allowed to run negative.", "From surface down to the fluid level standing in the annulus."]'::jsonb, 2, 'The floor means no credit is given for a pump set below the perforations, and the gradient used over that distance is an input the module never models.'),
  ('esp', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'Which statements from this tier stay in force once a design moves on past the stack?', '["The gradient may be taken from the whole stream once the duty rate has been fixed, since the two ever only differ on a well carrying a separator.", "The gradient belongs to the fluid inside the pump, the rate is an in situ rate, and the margin is bounded by one stage.", "The rate may revert to the tank liquid rate for reporting purposes, provided the stage curve reading itself was taken at the rate the pump sees at depth.", "The rounding margin may be quoted as a percentage design allowance, because by that point the stack length is settled and the percentage will not move again."]'::jsonb, 1, 'None of the three is a convenience that later work is allowed to relax, and each of them is the subject of a check that can be run on a finished report.'),
  ('esp', 'intermediate', 'final', null, 1, 'A vendor reads the gassyOffshore stream gas volume fraction of 0.0975609756, calls it close enough to the standard maximum to justify a gas handler, and asks why the design report still says standard. What answers the vendor?', '["The limits are applied to the fraction through the pump, which is 0.0314136126 once 201.600000 bbl/d has gone up the annulus, so a standard pump is the right class.", "The 0.10 default is a soft target rather than a limit.", "The stream fraction is formed before the volume factors are applied.", "Both fractions are compared, and the lower of the two decides."]'::jsonb, 0, 'The stream fraction has no consumer at all once the separator has been applied, so on a well with venting it is a reporting figure rather than a design input.'),
  ('esp', 'intermediate', 'final', null, 2, 'An annulus gradient is taken from the produced liquid rather than from the gassy column standing above the pump. Following that single input all the way to the stack, what does the designer end up holding?', '["The same stack, since the annulus gradient cancels out of the head.", "A warning, because the module checks the annulus gradient against the pumped fluid.", "An intake pressure that is too high, so less free gas, a friendlier verdict, a smaller pressure rise and a stack that is short.", "A stack that is too long, because the heavier annulus gradient removes pressure from the intake and leaves the pump a larger rise to make across the same tubing string."]'::jsonb, 2, 'Nothing objects, because the module used exactly the gradient it was handed and has no annulus model behind that number.'),
  ('esp', 'intermediate', 'final', null, 3, 'highWaterCut liberates 8000.00 scf/d out of a producing gas oil ratio of 200.0 scf/stb against 180.0 scf/stb in solution, so a small revision to the solution gas moves that difference by a large fraction of itself. Which outputs move with it, and which does not?', '["The mixture density and the gradient move, while the verdict stays standard because 14.400000 bbl/d is far below either published limit.", "The verdict moves first, since a gas volume fraction built on a difference of two close numbers is the most sensitive quantity in the whole intake calculation and crosses 0.10 readily.", "Only the free gas at depth moves, and it stops there.", "Nothing downstream moves, because the free gas on this well is floored at zero and a floored quantity cannot propagate an input revision anywhere at all."]'::jsonb, 0, 'The floor at zero bites only where the solution gas exceeds the producing gas oil ratio, and it is a floor rather than a diagnosis.'),
  ('esp', 'intermediate', 'final', null, 4, 'Lifting the separator efficiency on QUA-IBOE-4 from 0.4500 to 0.7000 moves the verdict from gasHandler to standard. What else does that move buy, and what does it cost?', '["The duty falls and the fluid gets lighter, because venting takes mass out of the stream and a stream carrying less mass weighs less per unit of volume at the intake.", "Only the verdict moves, since separator efficiency is a labelling input carried beside the rate rather than one that enters the volumes at depth.", "The duty falls and the head requirement rises, because a smaller duty rate always needs more feet of head out of the same pressure difference across the pump.", "The duty falls to 2791.061538 bbl/d and the fluid gets heavier at 47.655921 lbm/ft3."]'::jsonb, 3, 'A heavier fluid needs more pressure for the same feet of head, so venting never simply makes a design easier.'),
  ('esp', 'intermediate', 'final', null, 5, 'Forming a gas volume fraction on gassyOffshore, a designer adds the 300.0 scf/stb of solution gas to the free gas first. What has been counted twice?', '["The vented gas, which the separator already removed from the stream.", "Nothing, because a producing gas oil ratio of 500.0 scf/stb is the total gas.", "The gas still dissolved in the oil, which is already inside the 1440.000000 bbl/d of oil at depth through an oil formation volume factor of 1.2000.", "The free gas, since it is a difference of two rates rather than a rate."]'::jsonb, 2, 'Only gas that has broken out occupies its own space in an impeller, which is why the free gas is a difference and never the producing ratio.'),
  ('esp', 'intermediate', 'final', null, 6, 'Revising the annulus gradient upward on gassyOffshore lowers the pump intake pressure. Where does that revision surface in the three part reading of the head?', '["In the net vertical lift, which grows because less fluid stands above the intake, and in the head itself, which grows with the larger pressure difference.", "In the wellhead term, converted at a gradient that has moved.", "Nowhere, since the split is reported and not recomputed.", "In the tubing friction, which is the residual of the split and therefore absorbs every change made anywhere in the inputs to the head, the intake pressure included."]'::jsonb, 0, 'The friction bucket absorbs a discharge pressure error instead, because the net lift is built from the intake pressure and the wellhead term from the wellhead pressure.'),
  ('esp', 'intermediate', 'final', null, 7, 'Reading gasHandler on QUA-IBOE-4, a reviewer asks by how much the engine reduced the 23.57901945 ft per stage to allow for the gas. What is the honest reply?', '["By the gas volume fraction through the pump, which multiplies the head per stage as a degradation factor before the stage count is ever formed.", "By a factor taken from the separator efficiency, which is how the module carries the presence of gas into the stage reading it takes.", "By the amount the mixture density fell.", "By nothing at all, since the curve is read at the mixture rate as though the fluid were single phase."]'::jsonb, 3, 'Gas is present in the rate and in the density and nowhere else, so the verdict is the only output that knows there is any.'),
  ('esp', 'intermediate', 'final', null, 8, 'One gassyOffshore design converts 50.53658537 lbm/ft3 into its design gradient and then sizes the stack at a duty of 2750.400000 bbl/d. Which way is the resulting stage count wrong?', '["Too short, because a lighter fluid is easier to lift and a stage in it makes more head than the same stage would make in the heavier pumped mixture.", "Too long, because the lighter gradient turns 1860.0000 psi into more feet than the pumped fluid needs.", "Correct, because the density and the duty rate came out of the same intake calculation and the two errors that follow from them cancel in the division.", "Too long, because a whole stream rate of 2952.000000 bbl/d was used and a rate that far right on the curve reads a much smaller head per stage."]'::jsonb, 1, 'Taking the stream density with the vented rate sizes a pump for a fluid that exists nowhere in the well.'),
  ('esp', 'intermediate', 'final', null, 9, 'On IBENO-2 the two gradient routes part by 0.558191 ft while the integer ceiling on its stack buys 18.61783944 ft. Does the smaller figure stop mattering?', '["Yes, since any error smaller than the rounding margin is absorbed by the extra stage.", "Yes, because both are reported in feet and the larger of the two governs.", "No, because the gap in feet grows as the stack gets shorter.", "No. The two are unrelated quantities: one is a fixed 0.076982 percent of whatever head it sits on, and the other is the remainder of a ceiling that the next revision of the requirement will move."]'::jsonb, 3, 'The gap scales with the head while the margin is a sawtooth in the requirement, so no comparison between the two holds from one design to the next.'),
  ('esp', 'intermediate', 'final', null, 10, 'Both gradient conversions ship unchanged. Under what condition does the package actually return two different heads for one well?', '["When the drive frequency is not 60 Hz.", "When the head requirement exceeds the value quoted in the docstring.", "When a caller derives the specific gravity some other way, such as a density over 62.4, and hands that value to the diagnostics.", "When the design gradient is built from the whole stream density instead of the pumped mixture density, which is the only route by which the rounded field constant can reach a head."]'::jsonb, 2, 'On every shipped case the specific gravity is derived from the design gradient, so the two routes never meet and the disagreement stays unreachable.'),
  ('esp', 'intermediate', 'final', null, 11, 'Being careful, an engineer recomputes the highWaterCut specific gravity as 1.0137182991 from the density and passes it to the diagnostics while the design chain keeps its own gradient. What does the report now contain?', '["One head, because the diagnostics rebuild the design gradient from whatever specific gravity they are given and the chain stays consistent throughout.", "Two heads for one well, 3797.140461 ft and 3800.063587 ft, standing 2.923126 ft apart with neither of them flagged.", "One head and a corrected specific gravity of 1.0144986827.", "Two heads and a warning, since the module cross checks the specific gravity it was handed against the gradient it was handed before either one is used."]'::jsonb, 1, 'Deriving a true specific gravity fixes half a chain, and half a chain is the one configuration in which the convention costs anything.'),
  ('esp', 'intermediate', 'final', null, 12, 'A finished report prints a pressure difference of 2000.0 psi beside a blank head and a blank stage count. What happened, and at which step should a warning have fired?', '["The stage curve was read past the end of its published data, so the head per stage came back as NaN and carried that through the division into the stack length.", "The head per stage was negative, which the stage count refuses by returning NaN, and the warning belongs at the point the drive frequency was set.", "The discharge pressure was missing, so the module reported the intake pressure alone and declined the head, with the warning owed at the input stage.", "A gradient of zero reached the head, which returned NaN into the stage count, and no warning fires anywhere."]'::jsonb, 3, 'Half the return value is still live, which is what makes the failure quiet: it answered one question and declined the other in the same object.'),
  ('esp', 'intermediate', 'final', null, 13, 'Holding everything else on gassyOffshore, an oil formation volume factor revised away from 1.2000 moves the liquid density at depth. Through what?', '["Through the in situ oil volume of 1440.000000 bbl/d, which is the weight the oil density of 48.00 lbm/ft3 carries in a sum of masses over a sum of volumes.", "Through the water cut of 0.5000, which the volume factor rescales.", "Through the gas density, which is weighted against the liquid.", "Through the free gas at depth, which Bo scales along with the oil."]'::jsonb, 0, 'Both tank rates are equal on that well and the density still lands at 55.35135135 lbm/ft3 rather than the midpoint, because the volume factors moved the weighting first.'),
  ('esp', 'intermediate', 'final', null, 14, 'Where a separator has vented gas, converting 400.0 psia of wellhead pressure at the whole stream gradient instead of at the pumped gradient does what to that term?', '["It understates it, because the whole stream still carries the vented gas and a stream with gas in it weighs more per foot than the mixture the impellers actually see.", "It overstates it, because the stream is lighter by 0.0226698733 psi/ft and a lighter fluid buys more feet per psi.", "It leaves it unchanged, since the wellhead term is a pressure.", "It overstates it, because the stream gradient carries the annulus column."]'::jsonb, 1, 'Everything crossing into the stage curve is converted at the gradient of what is inside the pump, which is why the term is quoted in feet at all.'),
  ('esp', 'intermediate', 'final', null, 15, 'Sizing gassyOffshore on its tank liquid rate while still taking the gas volume fraction through the pump from the intake calculation, what comes out wrong, and why does the gas verdict stay silent about it?', '["The duty is high by that same factor of 1.11000000, so the stack comes out long, and the verdict is silent because the fraction through the pump is itself formed out of tank volumes.", "Nothing is wrong, because the uplift cancels in the stage count.", "The duty is low by a factor of 1.11000000, so the stack comes out short, and the verdict never sees the rate the sizing was read at.", "Only the efficiency is wrong, since head per stage is read against the head requirement rather than against any rate, and the gas verdict has no relationship with either quantity."]'::jsonb, 2, 'The gas volume fraction is a ratio of volumes at depth, so it is untouched by whichever rate a designer later reads the curve at.'),
  ('esp', 'intermediate', 'final', null, 16, 'QUA-IBOE-4 liberates 630000.00 scf/d, and its gas formation volume factor is brought down from reservoir conditions instead of being taken at 1432.0000 psia. Why can that one input change the equipment class when a wrong Bo would not?', '["Because Bo is bounded near one while Bg is bounded near zero, so an error in the smaller of the two constants is always the larger error in the product it appears in.", "Because the equipment class is decided on the whole stream fraction, which contains the gas volume alone and none of the liquid volumes that Bo and Bw between them produce.", "Because the gas formation volume factor also sets the gas density, so a wrong value moves the mixture density twice and the verdict follows the density rather than the fraction.", "Because Bg multiplies a quantity thousands of times larger, so the gas volume at depth swings the fraction through the pump across a published threshold."]'::jsonb, 3, 'On that well 882.000000 bbl/d of gas at depth exceeds the 776.461538 bbl/d of water, so the phase that looks trivial in standard volume is the largest one at the intake.'),
  ('esp', 'intermediate', 'final', null, 17, 'highWaterCut runs at 50 Hz, and a designer reads the 60 Hz stage curve straight at the duty of 4098.400000 bbl/d. What has been skipped, and what does skipping it cost?', '["The map back to an equivalent 4918.080000 bbl/d on the 60 Hz curve, so the head per stage is read at the wrong place and the 264 stage count moves with it.", "The downthrust warning, which is raised on the equivalent rate.", "Nothing, because the duty rate is already a rate at depth.", "The frequency correction on the density, which the drive sets."]'::jsonb, 0, 'The duty rate is a property of the well while the reference rate is a property of the reading, and only the second one moves with the drive.'),
  ('esp', 'intermediate', 'final', null, 18, 'A data sheet gives the highWaterCut water cut as 90 rather than as 0.9000. What does the module do with it?', '["It rejects the input and returns NaN through the liquid rate at depth, which is the mechanism by which an out of range fraction is kept away from the density calculation.", "It clamps the value into a valid fraction and carries on, so the mistake becomes a clamp rather than an error.", "It reads 90 percent and returns the same rates.", "It raises a warning and falls back on the supplied water rate."]'::jsonb, 1, 'The water rate is never an input on these cases: it follows from the oil rate and the cut, which is why 400.0 stb/d of oil carries 3600.000000 stb/d of water.'),
  ('esp', 'intermediate', 'final', null, 19, 'The gassyOffshore liquid at depth is 1.11000000 times its tank liquid rate. Adopting that as a rule of thumb and applying it to highWaterCut, whose true multiple is 1.02100000, what follows?', '["The duty is understated, because a wet well swells harder than an oily one and the multiple carried across from the gassy case is the smaller of the two.", "The duty is unchanged, since the multiple is dimensionless.", "The duty is overstated, so the curve is read right of the true point and every quantity read there is wrong together.", "Nothing follows, because the multiple applies to the liquid alone and the free gas at depth is added afterwards, which restores the rate through the pump to its correct value."]'::jsonb, 2, 'A wet well barely swells because water hardly expands, so the multiple has to be computed for the well in hand rather than carried across.'),
  ('esp', 'intermediate', 'final', null, 20, 'A report on QUA-IBOE-4 lists a duty of 3408.461538 bbl/d beside a design gradient built from 44.56935579 lbm/ft3. Which two statements in it disagree?', '["The rate is a stream rate at depth while the density is a liquid density at depth, so one of them includes the free gas and the other excluded it back at the tank.", "The rate has the separator uninstalled while the density has it applied.", "The rate is quoted at the drive frequency while the density is quoted at intake conditions, so the two belong to different points of one reading and cannot be put side by side.", "The rate is the liquid at depth while the density is the whole stream density, so the free gas has been left out of the volume and put into the mass at the same time."]'::jsonb, 1, 'Sizing on the lighter stream density with the vented rate takes the friendly half of each, and the duty at that separator setting is 3011.561538 bbl/d.'),
  ('esp', 'intermediate', 'final', null, 21, 'It is proposed that Bw be dropped from highWaterCut on the grounds that water hardly expands. What does that proposal actually remove?', '["The factor carrying almost the whole of this well''s liquid volume at depth, since 3600.000000 stb/d of water becomes 3636.000000 bbl/d against 448.000000 bbl/d of oil.", "The only volume factor evaluated at the intake pressure of 932.0000 psia.", "A factor with no consumer, because the water rate is derived and not supplied.", "The check that keeps the water cut inside a valid fraction."]'::jsonb, 0, 'An error that is quiet in percentage terms is not thereby small in barrels, and everything after the liquid rate inherits it.'),
  ('esp', 'intermediate', 'final', null, 22, 'A discharge pressure supplied too high still leaves a decomposition closing to 0.000000000000 ft. What has a reviewer who used that closure as a check actually confirmed?', '["That the discharge pressure is within a plausible range.", "That the friction term is arithmetic rather than a correlation.", "Only that the three parts were derived from the same pressures and the same gradient, which the error did not disturb.", "That the head, the net lift and the wellhead term are each consistent with the pressures supplied, since the sum is compared against a head computed independently of the three parts."]'::jsonb, 2, 'The whole of a discharge pressure error lands in the friction term, because the net lift comes from the intake pressure and the wellhead term from the wellhead pressure.'),
  ('esp', 'intermediate', 'final', null, 23, 'A gassyOffshore design writes 7500 ft TVD into the net lift. Name the two separate mistakes stacked inside that single entry.', '["A depth has replaced a fluid level, and the fluid level itself was read off a sonic shot in the annulus rather than computed from the intake pressure and the gradient of the pumped fluid.", "A depth has replaced a fluid level of 3413.452705 ft, and the depth chosen is the perforation depth rather than the 7000 ft TVD the pump sits at.", "The lift was floored at zero and the sign was then reversed.", "The perforation depth was used where the pump depth belongs, and the annulus gradient of 0.3200 psi/ft was used where the pumped gradient of 0.3736183828 psi/ft belongs in the same division."]'::jsonb, 1, 'The 500 ft between those two depths is annulus column worth 160.0000 psi, and it has already been paid inside the intake pressure.'),
  ('esp', 'intermediate', 'final', null, 24, 'A flowline change lowers the wellhead pressure on a design while the two pressures at the pump stay as they were. What moves?', '["The split moves, with feet passing from the wellhead term into the friction, and the head requirement does not move at all.", "The head requirement falls by the wellhead pressure divided by the gradient of the pumped fluid, and the stage count falls with it, since that term is one of the three the head is made of.", "The head requirement falls and the friction term stays where it is, because the friction came from a pipe correlation at the design rate and has no dependence on the wellhead pressure.", "Nothing moves until the discharge pressure is marched again, because the wellhead pressure enters the reading only through the flowing traverse that produced that discharge pressure."]'::jsonb, 0, 'Total dynamic head comes from the two pressures and the gradient alone, so a wellhead pressure only ever decides how the same number is reported.'),
  ('esp', 'intermediate', 'final', null, 25, 'IBENO-2 pays 59.0164 percent of its head into the wellhead term and 28.9634 percent into lift. What kind of well is that, and why does its stack deserve a second look?', '["A deep well with a long lift, whose stack is long enough to hide a bad stage reading.", "A well with an oversized separator, whose duty has been vented down too far.", "A well standing nearly full behind a live wellhead pressure, and its 725.090193 ft requirement buys only 33 stages, the length at which one rounded up stage is worth whole percent.", "A well sized in downthrust, where the region warning is what those two shares are reporting."]'::jsonb, 2, 'Nearly the whole column supports itself there, with 1889.989191 ft of fluid standing above the intake and only 210.010809 ft of lift left to pay for.'),
  ('esp', 'intermediate', 'final', null, 26, 'Two designs quote the same head requirement, one with its duty in the recommended region and one with its duty off the end of the published data. What does the requirement itself distinguish?', '["Nothing, because a head requirement is a statement about the well and says nothing about the stage that has to make it.", "The efficiency, which is carried inside the head.", "The region, which the head requirement is banded against.", "The second design, since a requirement computed from a duty outside the published range comes back with its range flag cleared and a warning naming the extrapolation."]'::jsonb, 0, 'The head is exact arithmetic on two pressures and a gradient, and reading it as a verdict on a design is what puts a stage reading beyond challenge.'),
  ('esp', 'intermediate', 'final', null, 27, 'One design builds its head from the whole stream gradient but converts its wellhead pressure at the pumped gradient. What happens when the three parts are summed against the head those two pressures gave?', '["It still lands on zero, because the sum adds the three parts it is handed and never goes back to the two pressures that produced the head in the first place.", "It still lands on zero, because the two gradients differ by only 0.0226698733 psi/ft and the residual is reported to twelve decimal places rather than to the precision that gap would need.", "The residual is no longer zero, and the module raises a gradient warning.", "The residual is no longer zero, and mixing two gradients on one well is the class of error that comparison does catch."]'::jsonb, 3, 'The exact closure on the shipped cases is a property of the three parts having been derived from the same inputs, so it survives a wrong pressure and not a mixed gradient.'),
  ('esp', 'intermediate', 'final', null, 28, 'A discharge pressure is taken from a static column of the pumped fluid standing above the pump. Why is that not the number the head calculation wants?', '["Because the module builds its own discharge pressure from the wellhead pressure and the tubing column, and any supplied value is overwritten before the head is formed.", "Because a discharge pressure is a flowing traverse result, marched at the design rate with the gas that is still in the stream.", "Because a static column understates the pressure by the friction, which the module then adds back from the tubing size and the roughness it was given for that string.", "Because a discharge pressure has to be quoted in gauge to match the wellhead pressure, and a column computed in absolute units shifts the head by an atmosphere."]'::jsonb, 1, 'This module has no tubing in it, so it will not build the number and it will not tell you that the one you supplied is wrong.'),
  ('esp', 'intermediate', 'final', null, 29, 'A reviewer waves through a 33 stage stack showing 2.567658 percent of spare head, having queried a 192 stage stack showing 0.037359 percent. Which of the two deserved the query?', '["The long one, since a small percentage of a large head is still many feet.", "Neither, because both figures are design margins that somebody chose.", "The short one, because the slack is bounded by a single stage however long the stack is, so it grows as a percentage exactly where there are fewer stages to share it.", "The short one, because a short stack is always sized in downthrust."]'::jsonb, 2, 'IBENO-2 carries less slack in stages than QUA-IBOE-4 and more than four times the percentage, so the two units rank the same four designs differently.'),
  ('esp', 'intermediate', 'final', null, 30, 'Raising a requirement from 650 ft to 680 ft on the short teaching stack takes it from 29 to 31 stages and the margin from 0.547939 percent to 2.740414 percent. What does a reader who tracks that margin as a design quantity get wrong?', '["That it is a quantity at all: it is the remainder of a ceiling, moving as a sawtooth and bearing on nothing about how the pump was chosen.", "That it is bounded, since it crossed a whole stage here.", "That it is comparable across two different pumps.", "That it is a percentage: the margin really is a design allowance, and the honest reading of the jump is that a longer stack has been given proportionally more spare head for the larger duty it now serves."]'::jsonb, 0, 'No threshold in the package fires on the margin and it is never carried into the warnings, because it exists only because stages come in ones.'),
  ('esp', 'intermediate', 'final', null, 31, 'A QUA-IBOE-4 report sizes the motor on 95.97003263 hp and then takes its amps from 95.41621294 hp. By how much is that chain inconsistent, and what is the quantity behind the gap?', '["By 0.55381969 hp, which is the hydraulic power lost in the stage efficiency, so the two figures are a fluid power and a shaft power and were never meant to agree.", "By nothing, since the published sizing method takes the power at the head the stack makes and the amps are always drawn off the same figure the motor was sized on.", "By one stage of brake power, 0.5579653060 hp.", "By 0.55381969 hp, which is the rounding margin: one stack read at the head it makes and at the head it was asked for."]'::jsonb, 3, 'Everything electrical in this package is built on the power at the head required, so a report mixing the two is inconsistent by exactly a ratio of two heads.'),
  ('esp', 'intermediate', 'final', null, 32, 'A report shows two brake powers whose ratio does not match the ratio of the two heads. What does that prove about the engine behind it?', '["That the stage count was rounded to nearest rather than up, since a count below the ceiling makes less head than the requirement and the two ratios then sit on opposite sides of one.", "That the two powers were taken at different specific gravities, because brake power is linear in gravity and the head ratio carries no gravity term to cancel it against.", "That it read the efficiency somewhere other than at the duty rate, which is the only way to break the identity.", "That nothing is wrong, because the two ratios agree only to the precision a double carries and a visible difference between them is ordinary floating point noise."]'::jsonb, 2, 'The identity holds because rounding moves the head and not the rate, and the efficiency is read at the rate, which is an input.'),
  ('esp', 'intermediate', 'final', null, 33, 'Hydraulic Institute factors of 0.85 on head and 0.70 on efficiency take a stage from 28.00000000 ft to 23.80000000 ft. What happens to the stack that stage sits in?', '["It needs more stages, and the brake power per stage falls with the head.", "It needs more stages for the same requirement and more brake power in each of them, because the efficiency was cut harder than the head.", "It is unchanged, since the factors are reported and not applied.", "It needs fewer stages, because the duty rate falls with the head."]'::jsonb, 1, 'That is a different pump rather than a longer one, and the module applies such factors only when a user hands them over.'),
  ('esp', 'intermediate', 'final', null, 34, 'QUA-IBOE-4 at 172 stages raises motorOverloaded, needing 95.4 hp against a 100 hp motor, and one remedy offered is to take stages out. Why is that on the list, and what does pulling it cost?', '["Stages are the only lever the sizing itself has, and pulling it costs head, because a shorter stack makes less of it.", "It is on the list because the region moves with the count.", "It costs efficiency, which falls away with a shorter stack.", "Stages are the cheapest lever available, and pulling it costs nothing measurable, because the rounding margin was bought precisely so a stage could come out without falling below the requirement."]'::jsonb, 0, 'The other remedy is a larger motor, and neither of them changes the duty rate or the region the stages run in.'),
  ('esp', 'intermediate', 'final', null, 35, 'A design review proposes rounding to nearest on the teaching well that divides out at 171.00742988 stages. What does the package do about the stack that results?', '["It returns NaN for the head made, because a stack below the ceiling cannot meet the head required and the margin would have to go negative for the arithmetic to close.", "It raises the underCurve diagnostic, since a stack making less head than its requirement is exactly the ratio that flag was written to catch on a running pump.", "It rounds the count back up and reports the change.", "Nothing at all: no warning in it fires on a stack that is short of its requirement."]'::jsonb, 3, 'A ceiling has no tolerance and no threshold, so a sliver of a stage past a whole number costs a whole one and the count is 172.'),
  ('esp', 'intermediate', 'final', null, 36, 'Sorting a set of design conditions into the chain is the first step of the method. What does sorting first actually catch?', '["Which of the pressures are absolute and which are gauge, since a wellhead pressure quoted in gauge shifts its term by an atmosphere that nobody wrote down anywhere.", "Which of the rates are at the tank and which are already at depth.", "Which of the volume factors were evaluated at the intake pressure, because the module cross checks each of them against the pressure it has just computed before using any.", "Which of the three densities belongs to the pumped mixture, since the whole stream density and the liquid density at depth are otherwise indistinguishable once venting is applied."]'::jsonb, 1, 'Nothing later in the chain repairs an error made earlier, because each step consumes the one before it and none of them looks back.'),
  ('esp', 'intermediate', 'final', null, 37, 'Of the checks this tier carries, which one catches a specific gravity that was formed by dividing a density by 62.4?', '["The friction identity, reconstructed from the discharge and wellhead pressures.", "The margin against one stage, which can never reach a whole stage.", "The two powers against the two heads, which agree to the last bit.", "The gradient route check, which reads the head twice and expects 0.000000000000 ft between the two, and returns 3.832442 ft on gassyOffshore when the specific gravity came off the density instead."]'::jsonb, 3, 'Divide the design gradient by 0.433 instead and the laundered value comes back, which is what the goldens were cut on.'),
  ('esp', 'intermediate', 'final', null, 38, 'An engineer finds a real and reproducible defect in one of these engines, prices it on four separate cases and opens a patch. What does this wave''s review say the professional output should have been?', '["A warning raised at the point the two routes are mixed.", "A deprecation of the rounded constant in the next release.", "A stated convention and a test that it holds, because the engine feeds a live application and a numeric edit moves a number somebody is looking at today.", "A patch is the right output and the review agrees: of five findings examined in that wave, the four priced on shipped cases were changed and only the unreproducible one was recorded."]'::jsonb, 2, 'Five findings were examined in that review and exactly one was changed, a formatting fix that altered no arithmetic at all.'),
  ('esp', 'intermediate', 'final', null, 39, 'At the stage count a designer discovers the annulus gradient was wrong. Which of the earlier steps have to be run again?', '["Only the head and the stack, because the annulus gradient enters at the intake pressure while the black oil properties are evaluated against reservoir conditions rather than that pressure.", "Every one of them from the intake pressure forward, since each step consumes the one before it.", "None of them, because the gradient is a reporting input.", "Only the intake pressure and the net lift, since that gradient is used once and the rate through the pump is built from tank rates and volume factors that do not depend on it."]'::jsonb, 1, 'The intake pressure sets the conditions the properties are evaluated at, so it decides the free gas, the rates at depth, the density and everything following them.'),
  ('esp', 'intermediate', 'final', null, 40, 'The IBENO-2 electrical chain is built on 29.77428389 hp where the published sizing method takes 30.53878580 hp. Taken as a fraction of the power that published method uses, how large is the understatement and which way does it run?', '["0.577076 percent, and it runs conservatively, since this package sizes on the head the stack makes while the published method sizes on the head required rather than the reverse.", "0.037345 percent, and it runs in the non conservative direction, because the understatement is a fixed property of the ceiling and not of how many stages that ceiling produced.", "2.503380 percent, and it runs conservatively, because a smaller shaft power sizes a larger motor and the difference therefore lands on the safe side of the plate.", "2.503380 percent, and it runs in the non conservative direction."]'::jsonb, 3, 'It was recorded for a human decision rather than fixed, because every number in this engine is consumed by a live application.'),
  ('esp', 'intermediate', 'final', null, 41, 'A finished report gives the head, its three parts, the stage count and both powers, but none of the inputs behind them. Which of this tier''s checks can still be run on it?', '["The three parts against the head, the two powers against the two heads, and the margin against one stage, while the friction identity needs the discharge and wellhead pressures the report withheld.", "None of them, because every check in the tier starts from the intake pressure.", "All of them, since each check is arithmetic on quantities that were reported.", "Only the friction identity, which is a statement about pressures alone."]'::jsonb, 0, 'The gradient route check also needs an input, since it turns on where the specific gravity came from rather than on anything the report prints.'),
  ('esp', 'intermediate', 'final', null, 42, 'Two of the four cases worked through this tier are published golden designs and two are teaching wells built for the wave. What may a reader take from a number that appears only on a teaching well?', '["The same standing as any golden, since both kinds run the same engine.", "Only the verdict, because the rates on a teaching well are invented.", "The behaviour it was built to show, since both published designs come back standard and neither reaches a threshold, but never the standing of a published value.", "Nothing at all, because a teaching well is an illustration rather than a case, and any conclusion drawn from one has to be confirmed against a published golden design before use."]'::jsonb, 2, 'QUA-IBOE-4 exists because both published designs return standard, and IBENO-2 exists because both published stacks are long.');
